import re

def parse(lines):
    blocks = []
    skip = []
    info = {}
    info_lines = []
    conf = {}
    conf_lines = []
    rows = []
    use_lines = []
    section = None
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        m = re.match(r'Attaching to process ID (\d+)', s)
        if m:
            info['pid'] = m.group(1)
            info_lines.append(i)
            continue
        m = re.match(r'JVM version is (\S+)', s)
        if m:
            info['JVM version'] = m.group(1)
            info_lines.append(i)
            continue
        m = re.match(r'(.*\S) GC with (\d+) thread', s)
        if m:
            info['GC'] = m.group(1)
            info['GC threads'] = m.group(2)
            info_lines.append(i)
            continue
        if s == 'Heap Configuration:':
            section = 'conf'
            skip.append(i)
            continue
        if s == 'Heap Usage:':
            section = 'usage'
            skip.append(i)
            continue
        if section == 'conf':
            m = re.match(r'(\w+)\s*=\s*(.*\S)$', s)
            if m:
                conf[m.group(1)] = m.group(2)
                conf_lines.append(i)
                continue
        elif section == 'usage':
            m = re.match(r'(.*\S):$', s)
            if m and not l[0].isspace():
                cur = {'Space': m.group(1)}
                rows.append(cur)
                use_lines.append(i)
                continue
            m = re.match(r'(\w+)\s*=\s*(\d+)', s)
            if m and cur is not None:
                cur[m.group(1)] = int(m.group(2))
                use_lines.append(i)
                continue
            m = re.match(r'([\d.]+)% used$', s)
            if m and cur is not None:
                cur['used %'] = float(m.group(1))
                use_lines.append(i)
                continue
        elif section is None:
            skip.append(i)
    rows = [r for r in rows if len(r) > 1]
    keys = []
    for r in rows:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = [dict((k, r.get(k, '')) for k in keys) for r in rows]
    if info:
        blocks.append({'name': 'jvm', 'kind': 'kv', 'lines': info_lines, 'records': [info]})
    if conf:
        blocks.append({'name': 'heap_configuration', 'kind': 'kv', 'lines': conf_lines, 'records': [conf]})
    if rows:
        blocks.append({'name': 'heap_usage', 'kind': 'table', 'lines': use_lines, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
